// spec: .qa/e2e/specs/navigation.md (2.1)
// seed: tests/seed.spec.ts (гость, без сессии)
import { test, expect } from '@playwright/test';

test.use({ storageState: { cookies: [], origins: [] } });

test.describe('Навигация — гость', () => {
  test('Гость: защищённые адреса ведут на /welcome, «כניסה» и «יצירת חשבון» возвращаются «חזרה» #fb3b8d53 @iphone @prod-safe', async ({ page }) => {
    // 1. / → /welcome: логотип, слоган, две кнопки
    await page.goto('/');
    await expect(page).toHaveURL(/\/welcome/);
    await expect(page.getByRole('img', { name: 'Banci' }).filter({ visible: true })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'השקט שלכם גם ליד המים' }).filter({ visible: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'יצירת חשבון' }).filter({ visible: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'כניסה', exact: true }).filter({ visible: true })).toBeVisible();
    // Иврит и RTL (только веб: атрибуты <html>)
    await expect(page.locator('html')).toHaveAttribute('lang', 'he');
    await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');

    // 2. «כניסה» → /sign-in → «חזרה» → /welcome
    await page.getByRole('button', { name: 'כניסה', exact: true }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/sign-in/);
    await expect(page.getByRole('heading', { name: 'כניסה' }).filter({ visible: true })).toBeVisible();
    await page.getByRole('button', { name: 'חזרה' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/welcome/);

    // 3. «יצירת חשבון» → /sign-up → «חזרה» → /welcome
    await page.getByRole('button', { name: 'יצירת חשבון' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/sign-up/);
    await expect(page.getByRole('heading', { name: 'יצירת חשבון' }).filter({ visible: true })).toBeVisible();
    await page.getByRole('button', { name: 'חזרה' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/welcome/);

    // 4. Защищённые адреса без входа → /welcome (только веб: прямой ввод адреса)
    for (const p of ['/home', '/children', '/history', '/account', '/monitor']) {
      await page.goto(p);
      await expect(page, `адрес ${p}`).toHaveURL(/\/welcome/);
      await expect(page.getByRole('heading', { name: 'השקט שלכם גם ליד המים' }).filter({ visible: true })).toBeVisible();
    }
  });
});
